export const KEY = 'stillwater.sanctuary.v1';
export function cleanName(v) {
  return typeof v === 'string'
    ? v
        .replace(/[\u0000-\u001f\u007f]/g, '')
        .trim()
        .slice(0, 24)
    : '';
}
export function freshState(now = Date.now()) {
  return {
    version: 3,
    pearls: 60,
    bank: 0,
    fish: [
      {uid: 'welcome-1', id: 'minnow', length: 9.4, ageBase: 1, bornAt: now, potential: 1, care: 0},
      {uid: 'welcome-2', id: 'perch', length: 13.2, ageBase: 1, bornAt: now, potential: 1, care: 0},
    ],
    found: ['minnow', 'perch'],
    total: 0,
    attempts: 0,
    rod: 0,
    line: 0,
    rodCondition: 100,
    rodBroken: false,
    tank: 0,
    filter: 0,
    regions: [0],
    region: 0,
    decor: [],
    quest: 0,
    storyChapter: 0,
    storyMode: true,
    fedCount: 0,
    perfectPulls: 0,
    tidesCompleted: 0,
    lastTideDay: -1,
    last: now,
    mood: 0,
    records: {},
    collectionClaimed: 0,
    quality: 'high',
    rayTracing: 'auto',
    musicOn: true,
    bredCount: 0,
    bait: 0,
    ownedBaits: ['bare'],
    baitStock: {},
    character: null,
    ownedClothes: ['shirt0', 'hat0', 'glasses0', 'pants0', 'shoes0'],
    outfit: {shirt: 'shirt0', hat: 'hat0', glasses: 'glasses0', pants: 'pants0', shoes: 'shoes0'},
    boat: 0,
    rebirth: 0,
    lifetimeEarned: 0,
    cameraMode: 'third',
    seenHelp: false,
    haptics: true,
    // Imperial for US English devices, metric everywhere else; changeable in Options.
    units: typeof navigator !== 'undefined' && /^en-US/i.test(navigator.language || '') ? 'imperial' : 'metric',
    audioOn: true,
    volume: 0.3,
  };
}
export function growth(f, now = Date.now()) {
  return Math.min(1, (f.ageBase ?? 1) + (Math.max(0, now - (f.bornAt ?? now)) / (45 * 60000)) * (f.potential || 1));
}
export function fishWeight(f, now = Date.now()) {
  const sp = SPECIES.find(x => x.id === f.id);
  const age = growth(f, now),
    cm = f.length * (0.64 + 0.36 * age);
  return Math.max(0.01, Math.pow(cm, 3) * 0.000012 * (sp?.shape === 'disc' ? 1.5 : sp?.shape === 'eel' ? 0.6 : 1));
}
export const QUALITY_TIERS = ['ultra-low', 'low', 'medium', 'high', 'very-high', 'ultra'];
export const MORPH_NAMES = {pearl: 'Pearl Iridescent', starlight: 'Starlight Shimmer', golden: 'Sunlit Gold'};
export function releaseValue(f, now = Date.now()) {
  const sp = SPECIES.find(x => x.id === f.id),
    morphMult = f.morph && MORPH_NAMES[f.morph] ? 1.35 : 1;
  return Math.floor(
    (sp?.value || 0) * (0.55 + growth(f, now) * 1.55) * (f.potential || 1) * (1 + (f.care || 0) * 0.32) * morphMult,
  );
}
export function income(s, now = Date.now()) {
  const storyBonus = 1 + (s.storyChapter || 0) * 0.03;
  return (
    s.fish.reduce(
      (a, f) =>
        a +
        (SPECIES.find(x => x.id === f.id)?.rate || 0) *
          (0.45 + 0.55 * growth(f, now)) *
          (1 + (f.care || 0) * 0.25) *
          (f.morph && MORPH_NAMES[f.morph] ? 1.3 : 1),
      0,
    ) *
    0.22 *
    (1 + s.decor.length * 0.1 + s.filter * 0.15) *
    (1 + s.rebirth * 0.25) *
    storyBonus
  );
}
export function accrue(s, now = Date.now()) {
  const secs = Math.min(8 * 3600, Math.max(0, (now - s.last) / 1000)),
    add = secs * income(s, (now + s.last) / 2);
  s.bank += add;
  s.last = now;
  return add;
}
export function sanitize(raw, now = Date.now()) {
  const s = {...freshState(now), ...raw};
  const n = (v, d = 0) => (Number.isFinite(v) && v >= 0 ? v : d);
  s.version = 3;
  s.audioOn = s.audioOn !== false;
  s.haptics = s.haptics !== false;
  s.storyMode = s.storyMode !== false;
  s.units = s.units === 'imperial' ? 'imperial' : 'metric';
  s.volume = Number.isFinite(s.volume) ? Math.max(0, Math.min(0.6, s.volume)) : 0.3;
  for (const k of ['pearls', 'bank', 'total', 'attempts', 'lifetimeEarned', 'fedCount', 'perfectPulls', 'tidesCompleted'])
    s[k] = n(s[k], k === 'pearls' ? 60 : 0);
  s.lastTideDay = Number.isInteger(s.lastTideDay) ? s.lastTideDay : -1;
  for (const [k, max] of [
    ['rod', RODS.length - 1],
    ['line', LINES.length - 1],
    ['tank', 3],
    ['filter', 3],
    ['quest', QUESTS.length],
    ['storyChapter', STORY_CHAPTERS.length],
    ['mood', 2],
    ['boat', 2],
    ['rebirth', 3],
    ['collectionClaimed', COLLECTION_GOALS.length],
  ])
    s[k] = Math.min(max, Math.floor(n(s[k])));
  s.rodCondition = Math.min(100, n(s.rodCondition, 100));
  s.rodBroken = !!s.rodBroken;
  s.last = Math.min(now, n(s.last, now));
  s.fish = (Array.isArray(s.fish) ? s.fish : [])
    .filter(f => f && SPECIES.some(x => x.id === f.id) && typeof f.uid === 'string' && /^[\w-]{1,100}$/.test(f.uid))
    .slice(0, TANKS[s.tank].capacity)
    .map(f => ({
      ...f,
      length: n(f.length, 12),
      nickname: cleanName(f.nickname),
      ageBase: Math.min(1, n(f.ageBase, 1)),
      bornAt: Math.min(now, n(f.bornAt, now)),
      potential: Math.max(0.8, Math.min(1.6, n(f.potential, 1))),
      care: Math.min(3, Math.floor(n(f.care))),
      ...(f.morph && MORPH_NAMES[f.morph] ? {morph: f.morph} : {}),
    }));
  s.found = [...new Set((Array.isArray(s.found) ? s.found : []).filter(id => SPECIES.some(x => x.id === id)))];
  s.decor = [...new Set((Array.isArray(s.decor) ? s.decor : []).filter(id => DECOR.some(x => x.id === id)))];
  s.regions = [
    ...new Set([
      0,
      ...(Array.isArray(s.regions) ? s.regions : []).filter(i => Number.isInteger(i) && i >= 0 && i < REGIONS.length),
    ]),
  ];
  s.region = s.regions.includes(s.region) ? s.region : 0;
  const qMap = {battery: 'low', balanced: 'medium', crisp: 'high'};
  if (qMap[s.quality]) s.quality = qMap[s.quality];
  s.quality = QUALITY_TIERS.includes(s.quality) ? s.quality : 'high';
  s.rayTracing = ['auto', 'on', 'off'].includes(s.rayTracing) ? s.rayTracing : 'auto';
  s.musicOn = s.musicOn !== false;
  s.bredCount = n(s.bredCount, 0);
  s.cameraMode = s.cameraMode === 'first' ? 'first' : 'third';
  const rec = s.records && typeof s.records === 'object' ? s.records : {};
  s.records = {};
  for (const f of SPECIES)
    s.records[f.id] = {
      count: Math.floor(n(rec[f.id]?.count)),
      best: Math.max(n(rec[f.id]?.best), ...s.fish.filter(x => x.id === f.id).map(x => x.length), 0),
    };
  const stock = s.baitStock || {};
  s.ownedBaits = [
    ...new Set([
      'bare',
      ...(Array.isArray(s.ownedBaits) ? s.ownedBaits : []).filter(id => BAITS.some(b => b.id === id)),
      ...BAITS.filter((b, i) => stock[b.id] > 0 || i === s.bait).map(b => b.id),
    ]),
  ];
  s.bait = Math.min(BAITS.length - 1, Math.floor(n(s.bait)));
  if (!s.ownedBaits.includes(BAITS[s.bait].id)) s.bait = 0;
  s.baitStock = {};
  s.ownedClothes = [
    ...new Set([
      ...freshState(now).ownedClothes,
      ...(Array.isArray(s.ownedClothes) ? s.ownedClothes : []).filter(id => APPAREL.some(a => a.id === id)),
    ]),
  ];
  const outfit = s.outfit || {};
  s.outfit = {};
  for (const slot of ['shirt', 'hat', 'glasses', 'pants', 'shoes'])
    s.outfit[slot] = APPAREL.some(a => a.id === outfit[slot] && a.slot === slot && s.ownedClothes.includes(a.id))
      ? outfit[slot]
      : slot + '0';
  if (s.character && typeof s.character === 'object')
    s.character = {
      name: cleanName(s.character.name) || 'Angler',
      skin: Math.min(4, Math.floor(n(s.character.skin))),
      hair: Math.min(3, Math.floor(n(s.character.hair))),
      style: Math.min(5, Math.floor(n(s.character.style))),
      eyes: Math.min(4, Math.floor(n(s.character.eyes))),
      facial: Math.min(3, Math.floor(n(s.character.facial))),
    };
  else s.character = null;
  if (s.pending) {
    if (
      !SPECIES.some(f => f.id === s.pending.id) ||
      typeof s.pending.uid !== 'string' ||
      !/^\w[\w-]{0,99}$/.test(s.pending.uid)
    )
      delete s.pending;
    else
      s.pending = {
        ...s.pending,
        length: n(s.pending.length, 12),
        potential: Math.max(0.8, Math.min(1.6, n(s.pending.potential, 1))),
        ageBase: Math.min(1, n(s.pending.ageBase, 1)),
        bornAt: Math.min(now, n(s.pending.bornAt, now)),
        care: Math.min(3, Math.floor(n(s.pending.care))),
      };
  }
  return s;
}
export function apparelLuck(s) {
  return Object.values(s.outfit).reduce((a, id) => a + (APPAREL.find(x => x.id === id)?.luck || 0), 0);
}
export function effectiveRod(s) {
  return RODS[s.rodBroken ? 0 : s.rod];
}
// Milo's rotating Tide Request: one species from the player's unlocked waters each 20-minute world day.
export function dailyRequest(s, now = Date.now()) {
  const day = Math.floor(now / 1200000),
    unlocked = Array.isArray(s.regions) && s.regions.length ? s.regions : [0],
    pool = SPECIES.filter(f => unlocked.includes(f.region) && f.rarity <= Math.min(3, 1 + Math.floor(s.rod * 0.7)));
  const pickPool = pool.length ? pool : SPECIES.filter(f => f.region === 0);
  const hash = Math.abs(Math.sin(day * 97.13 + unlocked.length * 19.7) * 43758.5453) % 1;
  const species = pickPool[Math.floor(hash * pickPool.length)] || SPECIES[0];
  const bonus = 35 + species.rarity * 30 + species.region * 15;
  return {
    day,
    species,
    region: REGIONS[species.region],
    bonus,
    done: s.lastTideDay === day,
  };
}
export function rollFish(s, rng = Math.random, conditions = {rarity: 1, phase: 'day', weather: 'clear'}) {
  const salt = REGIONS[s.region].habitat === 'salt',
    pool = SPECIES.filter(f => (salt ? f.region >= 3 && f.region <= s.region : f.region < 3 && f.region <= s.region));
  const b = BAITS[s.bait] || BAITS[0];
  const luck = effectiveRod(s).luck + b.luck + apparelLuck(s) + s.rebirth * 0.12 + (s.storyChapter || 0) * 0.02;
  const weights = [60, 24, 7, 1, 0.07];
  const req = dailyRequest(s);
  const picks = pool.map(f => {
    const nocturnal = ['catfish', 'eel'].includes(f.shape) || /midnight|star|ghost|celestial/i.test(f.id);
    const time =
      conditions.phase === 'night' && nocturnal ? 1.8 : conditions.phase === 'dawn' && f.shape === 'trout' ? 1.8 : 1;
    // Slight nudge toward Milo's active Tide Request if fishing in its home water.
    const tideBoost = !req.done && req.species.id === f.id ? 1.25 : 1;
    return {
      f,
      w:
        weights[f.rarity] *
        Math.pow(1 + luck * 0.5, f.rarity) *
        Math.pow(conditions.rarity || 1, f.rarity * 0.45) *
        time *
        tideBoost,
    };
  });
  let r = rng() * picks.reduce((a, p) => a + p.w, 0),
    sp = picks.at(-1).f;
  for (const p of picks) {
    r -= p.w;
    if (r <= 0) {
      sp = p.f;
      break;
    }
  }
  const baby = rng() < 0.36,
    base = (7 + sp.size * 8 + rng() * sp.size * 12) * (sp.region >= 5 ? 2.2 : sp.region >= 3 ? 1.4 : 1);
  const morphRoll = rng();
  const morph =
    morphRoll < 0.03 + luck * 0.015
      ? ['pearl', 'starlight', 'golden'][Math.floor(rng() * 3)]
      : undefined;
  return {
    uid: 'fish-' + Date.now() + '-' + Math.floor(rng() * 1e9),
    id: sp.id,
    length: Math.round(base * 10) / 10,
    ageBase: baby ? 0.2 : 1,
    bornAt: Date.now(),
    potential: Math.round((0.8 + rng() * 0.8) * 100) / 100,
    care: 0,
    ...(morph ? {morph} : {}),
  };
}
export function buy(s, kind, index) {
  accrue(s);
  let cost = 0;
  const tables = {rod: RODS, line: LINES, tank: TANKS, boat: BOATS};
  if (tables[kind]) {
    const t = tables[kind];
    if (index !== s[kind] + 1 || !t[index]) return false;
    cost = t[index].cost;
  } else if (kind === 'filter') {
    if (s.filter >= 3) return false;
    cost = [480, 2400, 11000][s.filter];
  } else if (kind === 'region') {
    if (s.regions.includes(index) || !REGIONS[index] || !s.regions.includes(index - 1)) return false;
    cost = REGIONS[index].cost;
  } else if (kind === 'decor') {
    if (!DECOR[index] || s.decor.includes(DECOR[index].id)) return false;
    cost = DECOR[index].cost;
  } else if (kind === 'bait') {
    if (!BAITS[index] || index === 0 || s.ownedBaits.includes(BAITS[index].id)) return false;
    cost = BAITS[index].cost;
  } else if (kind === 'apparel') {
    if (!APPAREL[index] || s.ownedClothes.includes(APPAREL[index].id)) return false;
    cost = APPAREL[index].cost;
  } else if (kind === 'repair') {
    if (s.rod === 0 || (!s.rodBroken && s.rodCondition >= 99)) return false;
    cost = repairCost(s);
  } else return false;
  if (s.pearls < cost) return false;
  s.pearls -= cost;
  if (tables[kind]) s[kind] = index;
  if (kind === 'rod') {
    s.rodBroken = false;
    s.rodCondition = 100;
  }
  if (kind === 'filter') s.filter++;
  if (kind === 'region') s.regions.push(index);
  if (kind === 'decor') s.decor.push(DECOR[index].id);
  if (kind === 'bait') {
    const b = BAITS[index];
    s.ownedBaits.push(b.id);
    s.bait = index;
  }
  if (kind === 'apparel') {
    const a = APPAREL[index];
    s.ownedClothes.push(a.id);
    s.outfit[a.slot] = a.id;
  }
  if (kind === 'repair') {
    s.rodBroken = false;
    s.rodCondition = 100;
  }
  return true;
}
export function repairCost(s) {
  return Math.max(12, Math.ceil(RODS[s.rod].cost * 0.12 * (1 - s.rodCondition / 100)));
}
export function keepFish(s, f) {
  if (s.fish.length >= TANKS[s.tank].capacity) return false;
  accrue(s);
  s.fish.push({...f});
  return true;
}
export function collect(s) {
  accrue(s);
  const amount = Math.floor(s.bank);
  s.pearls += amount;
  s.lifetimeEarned += amount;
  s.bank -= amount;
  return amount;
}
export function recordCatch(s, f) {
  const r = s.records[f.id] || {count: 0, best: 0};
  r.count++;
  r.best = Math.max(r.best, f.length);
  s.records[f.id] = r;
}
export function claimCollection(s) {
  const g = COLLECTION_GOALS[s.collectionClaimed];
  if (!g || s.found.length < g.target) return 0;
  s.pearls += g.reward;
  s.lifetimeEarned = (s.lifetimeEarned || 0) + g.reward;
  s.collectionClaimed++;
  return g.reward;
}
export function claimStoryChapter(s) {
  const ch = STORY_CHAPTERS[s.storyChapter || 0];
  if (!ch) return 0;
  const p = ch.progress(s);
  if (p.current < p.target) return 0;
  s.pearls += ch.reward;
  s.lifetimeEarned = (s.lifetimeEarned || 0) + ch.reward;
  s.storyChapter = (s.storyChapter || 0) + 1;
  return ch.reward;
}
export function nurture(s, uid) {
  const f = s.fish.find(f => f.uid === uid);
  if (!f || f.care >= 3) return false;
  const sp = SPECIES.find(x => x.id === f.id),
    cost = Math.ceil(sp.value * (f.care + 1) * 2.3);
  if (s.pearls < cost) return false;
  accrue(s);
  s.pearls -= cost;
  f.care++;
  f.bornAt = (f.bornAt ?? Date.now()) - 2 * 60000;
  return true;
}
export function feedResidents(s) {
  if (!s.fish.length || s.pearls < 8) return false;
  accrue(s);
  s.pearls -= 8;
  s.fedCount = (s.fedCount || 0) + 1;
  for (const f of s.fish) f.bornAt -= 2 * 60000;
  return true;
}
export function canRebirth(s) {
  return s.rebirth < 3 && s.total >= 100 && s.regions.includes(4) && s.pearls >= 25000;
}
export function rebirth(s) {
  if (!canRebirth(s)) return false;
  const keep = {
    audioOn: s.audioOn,
    haptics: s.haptics,
    units: s.units,
    volume: s.volume,
    ownedBaits: s.ownedBaits,
    bait: s.bait,
    character: s.character,
    outfit: s.outfit,
    ownedClothes: s.ownedClothes,
    found: s.found,
    records: s.records,
    rebirth: s.rebirth + 1,
    storyChapter: s.storyChapter || 0,
    storyMode: s.storyMode !== false,
    perfectPulls: s.perfectPulls || 0,
    tidesCompleted: s.tidesCompleted || 0,
    quality: s.quality,
    rayTracing: s.rayTracing,
    musicOn: s.musicOn,
    bredCount: s.bredCount || 0,
    cameraMode: s.cameraMode,
    seenHelp: true,
    lifetimeEarned: s.lifetimeEarned,
  };
  Object.keys(s).forEach(k => delete s[k]);
  Object.assign(s, freshState(), keep);
  return true;
}
export function canBreed(s, speciesId, now = Date.now()) {
  if (s.fish.length >= TANKS[s.tank].capacity) return false;
  const mates = s.fish.filter(f => f.id === speciesId && growth(f, now) >= 0.85);
  return mates.length >= 2;
}
export function breedCost(speciesId) {
  const sp = SPECIES.find(x => x.id === speciesId);
  return Math.max(18, Math.ceil((sp?.value || 12) * 1.4));
}
export function breedResidents(s, speciesId, now = Date.now(), rng = Math.random) {
  if (!canBreed(s, speciesId, now)) return null;
  const cost = breedCost(speciesId);
  if (s.pearls < cost) return null;
  const mates = s.fish.filter(f => f.id === speciesId && growth(f, now) >= 0.85);
  const sp = SPECIES.find(x => x.id === speciesId);
  accrue(s, now);
  s.pearls -= cost;
  s.bredCount = (s.bredCount || 0) + 1;
  const avgLen = (mates[0].length + mates[1].length) / 2,
    bestPot = Math.max(mates[0].potential || 1, mates[1].potential || 1),
    morphs = ['pearl', 'starlight', 'golden'],
    hasParentMorph = mates.find(m => m.morph)?.morph,
    morph = rng() < 0.55 ? (hasParentMorph || morphs[Math.floor(rng() * morphs.length)]) : undefined;
  const fry = {
    uid: 'fry-' + now + '-' + Math.floor(rng() * 1e9),
    id: sp.id,
    length: Math.round(avgLen * (1.02 + rng() * 0.08) * 10) / 10,
    ageBase: 0.15,
    bornAt: now,
    potential: Math.min(1.6, Math.round((bestPot + 0.06 + rng() * 0.1) * 100) / 100),
    care: 1,
    ...(morph ? {morph} : {}),
  };
  s.fish.push(fry);
  recordCatch(s, fry);
  return fry;
}
